<?php

defined('ABSPATH') || exit;

final class PLDR_Future_Derived_Text {
    public static function derive(int $edition_id,int $page,string $text,string $mode,string $target):array { $edition=PLDR_Future_Data::require_edition($edition_id);if(is_wp_error($edition))return array('error'=>$edition);$doc=PLDR_Core::document((int)$edition['document_id']);if($doc && 'patient-cases'===$doc['category'] && !apply_filters('pldr_derived_text_patient_case_allowed',false,$edition_id,$doc))return array('error'=>PLDR_Core::machine_error('pldr_derive_patient_case','Patient-case text is not sent to translation/transliteration providers without separate privacy approval.',403));$mode=sanitize_key($mode);if(!in_array($mode,array('translate','transliterate'),true))return array('error'=>PLDR_Core::machine_error('pldr_derive_mode','Use translate or transliterate mode.',400));$text=trim(wp_strip_all_tags($text));if(''===$text)return array('error'=>PLDR_Core::machine_error('pldr_derive_text','Text selection is required.',400));$filter='translate'===$mode?'pldr_translate_text':'pldr_transliterate_text';$result=apply_filters($filter,null,$text,array('edition_id'=>$edition_id,'page'=>$page,'source_language'=>$edition['language'],'target_language'=>sanitize_text_field($target)));if(!is_array($result)||empty($result['text']))return array('error'=>PLDR_Core::machine_error('pldr_derive_provider','No approved translation/transliteration provider is configured.',503,array('degraded'=>true)));return array('mode'=>$mode,'text'=>wp_strip_all_tags((string)$result['text']),'provider'=>sanitize_text_field((string)($result['provider']??'adapter')),'target_language'=>sanitize_text_field($target),'derived'=>true,'not_authorial_text'=>true,'original_unchanged'=>true); }
}
